        val hits   = hitCount.sum()
        val misses = missCount.sum()
        val total  = hits + misses
        return CacheStats(
            capacity   = CACHE_SIZE,
            populated  = populated,
            fillRatio  = populated.toFloat() / CACHE_SIZE,
            hits       = hits,
            misses     = misses,
            evictions  = evictionCount.sum(),
            hitRate    = if (total > 0) hits.toFloat() / total else 0f
