    @JvmField val CT_PERIMETER     = CalcType.PERIMETER.ordinal
    @JvmField val CT_POWER         = CalcType.POWER.ordinal
    @JvmField val CT_LOGARITHMIC   = CalcType.LOGARITHMIC.ordinal

