        companion object {
            fun from(c: Configuration) = ConfigSnapshot(
                screenWidthDp = c.screenWidthDp,
                screenHeightDp = c.screenHeightDp,
                smallestScreenWidthDp = c.smallestScreenWidthDp,
                densityDpi = c.densityDpi,
                fontScale = c.fontScale,
