        val capacity  : Int,
        val populated : Int,
        val fillRatio : Float,
        val hits      : Long = 0,
        val misses    : Long = 0,
        val evictions : Long = 0,
        val hitRate   : Float = 0f
    ) {
        override fun toString(): String =
            "DimenCache: $populated/$capacity slots used (${(fillRatio * 100).toInt()}% fill)" +
