    // AUTO-INIT — same guard as inline [getOrPut] ([isInitializedFast] + [init])
    if (context != null && !isInitializedFast) {
        init(context)
    }

    val h      = (key xor (key ushr 32)).toInt()
    val mixed  = h xor (h ushr 16)

