    const val BASE_DIAGONAL_DP = 611.6305f
    const val BASE_PERIMETER_DP = 833f
    const val REFERENCE_ASPECT_RATIO = 1.78f
    const val INV_REFERENCE_ASPECT_RATIO = 0.5617978f
