     * PT Limpa todas as entradas com lazySet (sem barrier completo por elemento) e
     * unrolling 4× para otimização de pipeline. Thread-safe.
     */
    @JvmStatic
    @JvmOverloads
    fun clearAll(context: Context? = null) {
        persistenceGeneration.incrementAndGet()
        persistenceGeneration.incrementAndGet()
