    // ─────────────────────────────────────────────────────────────────────────
    // CONFIGURATION & PERSISTENT STATE
    // ─────────────────────────────────────────────────────────────────────────

    internal val Context.dataStore: DataStore<Preferences> by preferencesDataStore(name = "com.appdimens.dynamic.cache")
