    @JvmStatic
    @Volatile
    @PublishedApi
    internal var diagnosticsEnabled: Boolean = false

    @JvmField val hitCount      = LongAdder()
    @JvmField val missCount     = LongAdder()
    @JvmField val evictionCount = LongAdder()

    /**
