        // https://github.com/Kotlin/dokka/issues/3701
        dokkaSourceSets.configureEach {
            suppress.set(name != "main")
        }
        dokkaSourceSets.register("main") {
            sourceRoots.from(file("src/main/java"), file("src/main/kotlin"))
